-- =====================================================================
-- Estadísticas de partido por jugador, a partir de las ACTAS de la Federación
-- Origen: BD federativa (ffv-postgres/statsbomb), tablas lineup/goal/card,
-- temporada 2026-27, 15 equipos del club 100718. 1207 filas (67 partidos con acta).
-- La ficha del jugador lee esta tabla (partidos, minutos, titular, goles, tarjetas).
-- Los jugadores se emparejan con `plantillas` por equipo (equipos.id_equipo_fed) y nombre.
-- Idempotente: se puede relanzar (borra y recarga las filas de origen 'federacion').
-- =====================================================================

CREATE TABLE IF NOT EXISTS estadisticas_partido_jugador (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    jugador_id UUID NOT NULL REFERENCES plantillas(id) ON DELETE CASCADE,
    equipo_id UUID NOT NULL REFERENCES equipos(id) ON DELETE CASCADE,
    fed_match_id INTEGER NOT NULL,
    fecha DATE NOT NULL,
    jornada VARCHAR(10),
    competicion TEXT,
    rival TEXT,
    es_local BOOLEAN,
    titular BOOLEAN NOT NULL DEFAULT FALSE,
    minutos INTEGER NOT NULL DEFAULT 0 CHECK (minutos >= 0),
    goles INTEGER NOT NULL DEFAULT 0 CHECK (goles >= 0),
    amarillas INTEGER NOT NULL DEFAULT 0,
    rojas INTEGER NOT NULL DEFAULT 0,
    origen VARCHAR(20) NOT NULL DEFAULT 'federacion',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (jugador_id, fed_match_id)
);

CREATE INDEX IF NOT EXISTS idx_est_partido_jugador_jugador ON estadisticas_partido_jugador(jugador_id);
CREATE INDEX IF NOT EXISTS idx_est_partido_jugador_equipo ON estadisticas_partido_jugador(equipo_id);

ALTER TABLE estadisticas_partido_jugador ENABLE ROW LEVEL SECURITY;

-- Solo lectura desde la app; la carga se hace por migración (service role).
DROP POLICY IF EXISTS "estadisticas_partido_jugador: leer si autenticado" ON estadisticas_partido_jugador;
CREATE POLICY "estadisticas_partido_jugador: leer si autenticado" ON estadisticas_partido_jugador
    FOR SELECT USING (auth.role() = 'authenticated');

CREATE OR REPLACE FUNCTION public._norm_key_fed(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $f$
    SELECT string_agg(w, ' ' ORDER BY w) FROM unnest(regexp_split_to_array(
        btrim(regexp_replace(translate(upper(COALESCE(t,'')), 'ÁÉÍÓÚÜÀÈÌÒÙ', 'AEIOUUAEIOU'), '[^A-Z0-9Ñ ]', ' ', 'g')),
        '\s+')) w WHERE w <> ''
$f$;

DO $$
DECLARE
    n_total INT; n_ok INT; r RECORD;
BEGIN
    CREATE TEMP TABLE fed_stats (team_id text, player_name text, dorsal int, fecha date, rival_raw text,
        jornada text, titular boolean, minutos int, goles int, amarillas int, rojas int, fed_match_id int,
        equipo_id uuid, jugador_id uuid, key text) ON COMMIT DROP;


    SELECT count(*) INTO n_total FROM fed_stats;

    UPDATE fed_stats f SET key = public._norm_key_fed(f.player_name),
        equipo_id = (SELECT e.id FROM equipos e WHERE e.id_equipo_fed = f.team_id LIMIT 1);

    -- 1) Coincidencia exacta de nombre (sin orden de palabras) dentro del equipo
    UPDATE fed_stats f SET jugador_id = (
        SELECT p.id FROM plantillas p
        WHERE p.equipo_id = f.equipo_id AND public._norm_key_fed(p.nombre) = f.key
        ORDER BY p.id LIMIT 1);

    -- 2) Si no, el nombre de la plantilla (>= 2 palabras) está contenido en el de la federación, de forma única
    UPDATE fed_stats f SET jugador_id = (
        SELECT p.id FROM plantillas p
        WHERE p.equipo_id = f.equipo_id
          AND array_length(string_to_array(public._norm_key_fed(p.nombre), ' '), 1) >= 2
          AND string_to_array(public._norm_key_fed(p.nombre), ' ') <@ string_to_array(f.key, ' '))
    WHERE f.jugador_id IS NULL AND f.equipo_id IS NOT NULL
      AND (SELECT count(*) FROM plantillas p
           WHERE p.equipo_id = f.equipo_id
             AND array_length(string_to_array(public._norm_key_fed(p.nombre), ' '), 1) >= 2
             AND string_to_array(public._norm_key_fed(p.nombre), ' ') <@ string_to_array(f.key, ' ')) = 1;

    DELETE FROM estadisticas_partido_jugador WHERE origen = 'federacion';

         titular, minutos, goles, amarillas, rojas)
    SELECT DISTINCT ON (f.jugador_id, f.fed_match_id)
           f.jugador_id, f.equipo_id, f.fed_match_id, f.fecha, 'J' || f.jornada, e.competicion,
           substr(f.rival_raw, 3), left(f.rival_raw, 1) = 'L',
           f.titular, f.minutos, f.goles, f.amarillas, f.rojas
    FROM fed_stats f JOIN equipos e ON e.id = f.equipo_id
    WHERE f.jugador_id IS NOT NULL
    ORDER BY f.jugador_id, f.fed_match_id, f.minutos DESC;

    SELECT count(*) INTO n_ok FROM estadisticas_partido_jugador WHERE origen = 'federacion';
    RAISE NOTICE 'Estadísticas cargadas: % de % filas de acta emparejadas', n_ok, n_total;

    FOR r IN SELECT DISTINCT team_id, player_name FROM fed_stats WHERE jugador_id IS NULL ORDER BY 1, 2 LOOP
        RAISE NOTICE 'Sin emparejar (equipo fed %): %', r.team_id, r.player_name;
    END LOOP;
END $$;

DROP FUNCTION IF EXISTS public._norm_key_fed(text);
